import { CLIENT_LOG_SYNC_TAG, shipPendingClientLogs } from './client-log-shipping.js';
import { createComponentLogger } from '../../utils/component-logger.js';

const log = createComponentLogger('client-logs');

export interface ClientLogSyncEventLike {
    readonly tag: string;
    waitUntil(promise: Promise<unknown>): void;
}

export function handleClientLogSyncEvent(
    event: ClientLogSyncEventLike,
    ship: () => Promise<unknown> = shipPendingClientLogs,
): boolean {
    if (event.tag !== CLIENT_LOG_SYNC_TAG) return false;
    const shipping = ship();
    // Story 451: offline is expected here. The catch keeps it from surfacing as an unhandled rejection;
    // waitUntil still gets the rejection, so Background Sync retries.
    shipping.catch((err: unknown) => {
        log.warn('ship failed; Background Sync retries', { error: err instanceof Error ? `${err.name}: ${err.message}` : String(err) });
    });
    event.waitUntil(shipping);
    return true;
}
