import type { ComponentLogger } from '../../utils/component-logger.js';

export interface QueueSyncEventLike {
    readonly tag: string;
    readonly lastChance: boolean;
    waitUntil(promise: Promise<unknown>): void;
}

/**
 * Story 462: runs a queue's Background Sync drain and logs the attempt. Without
 * it, a queue the browser stopped retrying left no trace. The log's own handlers
 * keep a failure from surfacing as an unhandled rejection; `waitUntil` still
 * gets the rejection, so the browser retries (story 451's pattern).
 */
export function traceQueueSync(event: QueueSyncEventLike, ship: () => Promise<unknown>, log: ComponentLogger): void {
    const { tag, lastChance } = event;
    log.info('Background Sync fired', { tag, lastChance });
    const shipping = ship();
    shipping.then(
        (result) => log.info('drained', { tag, result }),
        (err: unknown) => {
            const error = err instanceof Error ? `${err.name}: ${err.message}` : String(err);
            if (lastChance) {
                log.error('drain failed on the last Background Sync attempt; the queue waits for the next open, foreground or Debug › Ship queued', { tag, error });
            } else {
                log.warn('drain failed; Background Sync retries', { tag, error });
            }
        },
    );
    event.waitUntil(shipping);
}
